mapper.select:
	SELECT 

	FROM tb_board B

    WHERE 1 = 1
      AND (
            #{global} = 1

            OR B.BOARD_TYPE_CD IN ('FREE', 'ANON', 'NOTICE')

            OR B.FRST_RGTR_ID = #{currentEmpId}

            OR B.DEPT_CD = #{myDeptCd}


                OR B.DEPT_CD IN

                    #{deptCd}




                OR TO_CHAR(B.PROJ_ID) IN

                    #{projId}


      )


        AND (
            B.BOARD_SJ LIKE '%' || #{condition.keyword} || '%'
            OR B.BOARD_CN LIKE '%' || #{condition.keyword} || '%'
        )


    ORDER BY B.FRST_REG_DT DESC
